\section{Monotone Sequences and Completeness}

Throughout, $(a_n)_{n \ge 1}$ denotes a sequence of real numbers. We recall the basic definition and then prove that bounded monotone sequences converge, a statement that is equivalent to the completeness of $\mathbb{R}$.

\begin{definition}
We say that $(a_n)$ \emph{converges} to $L \in \mathbb{R}$, and write $a_n \to L$, if for every $\varepsilon > 0$ there exists $N \in \mathbb{N}$ such that $|a_n - L| < \varepsilon$ for all $n \ge N$.
\end{definition}

\begin{proposition}\label{prop:unique}
A sequence has at most one limit.
\end{proposition}

\begin{proof}
Suppose $a_n \to L$ and $a_n \to M$ with $L \ne M$. Let $\varepsilon = |L - M|/2 > 0$. Choose $N_1$ and $N_2$ such that $|a_n - L| < \varepsilon$ for $n \ge N_1$ and $|a_n - M| < \varepsilon$ for $n \ge N_2$. For $n = \max(N_1, N_2)$ the triangle inequality gives
\begin{align*}
|L - M| &\le |L - a_n| + |a_n - M| \\
        &< \varepsilon + \varepsilon = |L - M|,
\end{align*}
a contradiction.
\end{proof}

\begin{proposition}\label{prop:bounded}
Every convergent sequence is bounded.
\end{proposition}

\begin{proof}
Let $a_n \to L$. Taking $\varepsilon = 1$, there is $N$ with $|a_n - L| < 1$, hence $|a_n| < |L| + 1$, for all $n \ge N$. Put
\[
  B = \max\{|a_1|, |a_2|, \dots, |a_{N-1}|, |L| + 1\}.
\]
Then $|a_n| \le B$ for every $n$.
\end{proof}

The converse of Proposition~\ref{prop:bounded} is false, as $a_n = (-1)^n$ shows. However, it becomes true under an extra hypothesis.

\begin{theorem}[Monotone convergence]\label{thm:mct}
If $(a_n)$ is nondecreasing and bounded above, then $(a_n)$ converges, and
\[
  \lim_{n \to \infty} a_n = \sup\{a_n : n \ge 1\}.
\]
\end{theorem}

\begin{proof}
The set $A = \{a_n : n \ge 1\}$ is nonempty and bounded above, so by the completeness axiom it has a least upper bound $s = \sup A$. Let $\varepsilon > 0$. Since $s - \varepsilon < s$, the number $s - \varepsilon$ is not an upper bound of $A$, so there exists $N$ with $a_N > s - \varepsilon$. For every $n \ge N$, monotonicity and the definition of $s$ give
\begin{align*}
s - \varepsilon < a_N \le a_n \le s,
\end{align*}
hence $|a_n - s| < \varepsilon$. Therefore $a_n \to s$.
\end{proof}

By applying Theorem~\ref{thm:mct} to $(-a_n)$, a nonincreasing sequence that is bounded below converges to its infimum.

\begin{example}
Define $a_1 = 1$ and $a_{n+1} = \sqrt{2 + a_n}$. We claim $a_n \to 2$.

\emph{Bounded above by $2$.} We have $a_1 = 1 < 2$, and if $0 \le a_n < 2$ then $a_{n+1} = \sqrt{2 + a_n} < \sqrt{4} = 2$. By induction, $0 \le a_n < 2$ for all $n$.

\emph{Increasing.} For $0 \le x < 2$ we have
\begin{align*}
2 + x - x^2 = (2 - x)(1 + x) > 0,
\end{align*}
so $\sqrt{2 + x} > x$. Taking $x = a_n$ gives $a_{n+1} > a_n$.

By Theorem~\ref{thm:mct}, $a_n \to L$ for some $L$ with $1 \le L \le 2$. Since $a_{n+1}^2 = 2 + a_n$ and both sides converge, $L^2 = 2 + L$, so $(L - 2)(L + 1) = 0$. As $L \ge 1$, we conclude $L = 2$.
\end{example}

\begin{remark}
In the example, we needed to know that the limit exists before solving $L^2 = 2 + L$. Without that step the argument would be invalid: for instance, the recursion $b_{n+1} = 2 b_n$ with $b_1 = 1$ formally suggests $L = 2L$, so $L = 0$, although $b_n = 2^{n-1}$ diverges.
\end{remark}

\section{The Rank--Nullity Theorem}

Let $V$ and $W$ be vector spaces over a field $F$, and let $T \colon V \to W$ be a linear map. Recall the two subspaces naturally attached to $T$:
\begin{align*}
\ker T &= \{ v \in V : T v = 0 \} \subseteq V, \\
\operatorname{im} T &= \{ T v : v \in V \} \subseteq W.
\end{align*}
When these are finite-dimensional we write $\operatorname{nullity}(T) = \dim \ker T$ and $\operatorname{rank}(T) = \dim \operatorname{im} T$.

\begin{theorem}[Rank--nullity]\label{thm:rank-nullity}
If $V$ is finite-dimensional, then $\operatorname{im} T$ is finite-dimensional and
\[
  \dim V = \operatorname{rank}(T) + \operatorname{nullity}(T).
\]
\end{theorem}

\begin{proof}
Since $\ker T$ is a subspace of the finite-dimensional space $V$, it has a finite basis $u_1, \dots, u_k$, where $k = \operatorname{nullity}(T)$ (possibly $k = 0$). Extend this to a basis
\[
  u_1, \dots, u_k, v_1, \dots, v_r
\]
of $V$, so that $\dim V = k + r$. We show that $T v_1, \dots, T v_r$ is a basis of $\operatorname{im} T$, which gives $\operatorname{rank}(T) = r$ and proves the theorem.

\emph{Spanning.} Let $w \in \operatorname{im} T$, say $w = T v$. Write $v = \sum_{i=1}^{k} a_i u_i + \sum_{j=1}^{r} b_j v_j$. Since $T u_i = 0$ for each $i$,
\begin{align*}
w = T v &= \sum_{i=1}^{k} a_i\, T u_i + \sum_{j=1}^{r} b_j\, T v_j \\
        &= \sum_{j=1}^{r} b_j\, T v_j .
\end{align*}

\emph{Linear independence.} Suppose $\sum_{j=1}^{r} c_j\, T v_j = 0$. By linearity, $T\bigl(\sum_j c_j v_j\bigr) = 0$, so $\sum_j c_j v_j \in \ker T$. Hence there are scalars $d_1, \dots, d_k$ with
\[
  \sum_{j=1}^{r} c_j v_j = \sum_{i=1}^{k} d_i u_i,
  \qquad\text{that is,}\qquad
  \sum_{j=1}^{r} c_j v_j - \sum_{i=1}^{k} d_i u_i = 0.
\]
Since $u_1, \dots, u_k, v_1, \dots, v_r$ are linearly independent, all coefficients vanish; in particular $c_1 = \dots = c_r = 0$.
\end{proof}

\begin{corollary}\label{cor:inj-surj}
Let $T \colon V \to W$ be linear with $\dim V = \dim W = n < \infty$. Then the following are equivalent:
\begin{enumerate}
  \item $T$ is injective;
  \item $T$ is surjective;
  \item $T$ is bijective.
\end{enumerate}
\end{corollary}

\begin{proof}
$T$ is injective if and only if $\ker T = \{0\}$, that is, $\operatorname{nullity}(T) = 0$. By Theorem~\ref{thm:rank-nullity} this holds if and only if $\operatorname{rank}(T) = n$, which, because $\operatorname{im} T$ is a subspace of the $n$-dimensional space $W$, holds if and only if $\operatorname{im} T = W$. Thus (1) and (2) are equivalent, and each is therefore equivalent to (3).
\end{proof}

\begin{example}
Let $A$ be an $m \times n$ real matrix, viewed as a map $\mathbb{R}^n \to \mathbb{R}^m$. The image is the column space of $A$, and the kernel is the solution set of $A x = 0$. Row reduction to echelon form produces one free variable for each column without a pivot, and the free variables parametrize the kernel. So
\begin{align*}
\operatorname{nullity}(A) &= n - (\text{number of pivots}), \\
\operatorname{rank}(A) &= \text{number of pivots},
\end{align*}
in agreement with the theorem. For instance, the $2 \times 3$ matrix with rows $(1, 2, 3)$ and $(2, 4, 6)$ has a single pivot, so its rank is $1$ and its kernel is the plane $x + 2y + 3z = 0$ in $\mathbb{R}^3$, of dimension $2$.
\end{example}

\begin{remark}
The corollary fails in infinite dimensions. On the space of real polynomials, differentiation is surjective but not injective, while multiplication by $x$ is injective but not surjective.
\end{remark}

\section{Euler's Formula for Planar Graphs}

A graph is \emph{planar} if it can be drawn in the plane so that edges meet only at shared endpoints. Such a drawing is called a \emph{plane embedding}. The edges of a plane embedding divide the plane into connected regions called \emph{faces}, exactly one of which is unbounded.

Throughout, $V$, $E$, and $F$ denote the numbers of vertices, edges, and faces of a plane embedding. We allow multiple edges and loops only where stated; the corollaries concern simple graphs.

\begin{theorem}[Euler's formula]\label{thm:euler}
For every connected plane graph,
\[
  V - E + F = 2.
\]
\end{theorem}

\begin{proof}
We argue by induction on $E$, keeping $V$ fixed.

\emph{Base case.} A connected graph on $V$ vertices has at least $V - 1$ edges. If $E = V - 1$, the graph is a tree. A tree contains no cycle, so its drawing does not separate the plane, and $F = 1$. Then
\begin{align*}
V - E + F = V - (V - 1) + 1 = 2.
\end{align*}

\emph{Inductive step.} Suppose $E \ge V$, so the graph is not a tree and therefore contains a cycle $C$. Let $e$ be an edge of $C$. By the Jordan curve theorem, the drawing of $C$ separates the plane into an inside and an outside, and the two sides of $e$ lie in different faces. Deleting $e$ merges these two faces into one, while the graph stays connected because the rest of $C$ still joins the endpoints of $e$. The new plane graph has $V$ vertices, $E - 1$ edges and $F - 1$ faces, and by the induction hypothesis
\[
  V - (E - 1) + (F - 1) = 2,
\]
which is the same as $V - E + F = 2$.
\end{proof}

\begin{corollary}\label{cor:3v6}
If $G$ is a simple connected planar graph with $V \ge 3$, then
\[
  E \le 3V - 6.
\]
\end{corollary}

\begin{proof}
Fix a plane embedding. For each face, walk once around its boundary and record the length of this boundary walk. Every edge is traversed exactly twice in total over all faces (once from each side, possibly by the same face), so the lengths sum to $2E$. Because $G$ is simple and has at least three vertices, every boundary walk has length at least $3$. Hence
\begin{align*}
3F &\le 2E, \\
\intertext{and substituting $F = 2 - V + E$ from Theorem~\ref{thm:euler},}
3(2 - V + E) &\le 2E, \\
E &\le 3V - 6. \qedhere
\end{align*}
\end{proof}

\begin{corollary}\label{cor:k5}
The complete graph $K_5$ is not planar.
\end{corollary}

\begin{proof}
$K_5$ has $V = 5$ and $E = \binom{5}{2} = 10$. But $3V - 6 = 9 < 10$, contradicting Corollary~\ref{cor:3v6}.
\end{proof}

\begin{corollary}\label{cor:k33}
The complete bipartite graph $K_{3,3}$ is not planar.
\end{corollary}

\begin{proof}
Here $V = 6$ and $E = 9$, and $9 \le 3 \cdot 6 - 6 = 12$, so Corollary~\ref{cor:3v6} gives no contradiction. We use instead that $K_{3,3}$ is bipartite, so it has no cycles of odd length, and in particular no triangles. In a plane embedding every boundary walk would therefore have length at least $4$, giving $4F \le 2E$. With $F = 2 - V + E = 5$ this says $20 \le 18$, which is false.
\end{proof}

\begin{remark}
More generally, a simple connected planar graph with $V \ge 3$ and no triangles satisfies $E \le 2V - 4$. Kuratowski's theorem states that a graph is planar if and only if it contains no subdivision of $K_5$ or $K_{3,3}$; the corollaries above prove the easy direction for these two graphs.
\end{remark}

\section{Markov and Chebyshev Inequalities}

Concentration inequalities bound the probability that a random variable lies far from a reference value, using only limited information about its distribution. The two most basic examples require knowledge of nothing more than the mean, or the mean and the variance.

Throughout, $X$ is a real random variable on a probability space $(\Omega, \mathcal{F}, \mathbb{P})$, and we write $\mathbb{E}$ for expectation.

\begin{theorem}[Markov's inequality]\label{thm:markov}
If $X \ge 0$ and $a > 0$, then
\[
  \mathbb{P}(X \ge a) \le \frac{\mathbb{E}[X]}{a}.
\]
\end{theorem}

\begin{proof}
Let $\mathbf{1}_{\{X \ge a\}}$ be the indicator of the event $\{X \ge a\}$. We claim that
\[
  a \, \mathbf{1}_{\{X \ge a\}} \le X
\]
pointwise on $\Omega$. Indeed, where $X \ge a$ the left side equals $a \le X$, and elsewhere it equals $0 \le X$ because $X$ is nonnegative. Taking expectations, which preserves inequalities,
\begin{align*}
a \, \mathbb{P}(X \ge a) = \mathbb{E}\bigl[a \, \mathbf{1}_{\{X \ge a\}}\bigr] \le \mathbb{E}[X].
\end{align*}
Dividing by $a$ completes the proof.
\end{proof}

The hypothesis $X \ge 0$ cannot be dropped: if $X$ takes the values $-100$ and $1$ with equal probability, then $\mathbb{E}[X] < 0$ while $\mathbb{P}(X \ge 1) = 1/2$.

\begin{theorem}[Chebyshev's inequality]\label{thm:chebyshev}
Suppose $X$ has finite mean $\mu$ and finite variance $\sigma^2$. Then for every $k > 0$,
\[
  \mathbb{P}\bigl(|X - \mu| \ge k\bigr) \le \frac{\sigma^2}{k^2}.
\]
\end{theorem}

\begin{proof}
Apply Theorem~\ref{thm:markov} to the nonnegative random variable $Y = (X - \mu)^2$ with $a = k^2$. Since $|X - \mu| \ge k$ if and only if $Y \ge k^2$,
\begin{align*}
\mathbb{P}\bigl(|X - \mu| \ge k\bigr) &= \mathbb{P}\bigl(Y \ge k^2\bigr) \\
  &\le \frac{\mathbb{E}[(X - \mu)^2]}{k^2} = \frac{\sigma^2}{k^2}. \qedhere
\end{align*}
\end{proof}

Writing $k = t\sigma$ with $t > 0$ gives the equivalent form $\mathbb{P}(|X - \mu| \ge t\sigma) \le 1/t^2$. For example, any distribution with finite variance places at most $1/4$ of its probability at two or more standard deviations from the mean.

\begin{example}
A fair coin is tossed $100$ times. Let $S$ be the number of heads. Then $S$ is a sum of $100$ independent indicators with mean $1/2$ and variance $1/4$, so
\begin{align*}
\mathbb{E}[S] &= 50, & \operatorname{Var}(S) &= 100 \cdot \tfrac{1}{4} = 25.
\end{align*}
Chebyshev's inequality yields
\[
  \mathbb{P}\bigl(|S - 50| \ge 10\bigr) \le \frac{25}{100} = \frac{1}{4}.
\]
The true probability is considerably smaller, roughly $0.057$; Chebyshev's bound is crude but requires no knowledge of the shape of the distribution.
\end{example}

\begin{theorem}[Weak law of large numbers]\label{thm:wlln}
Let $X_1, X_2, \dots$ be pairwise uncorrelated random variables, each with mean $\mu$ and variance $\sigma^2 < \infty$, and let $\bar{X}_n = \frac{1}{n}\sum_{i=1}^n X_i$. Then for every $\varepsilon > 0$,
\[
  \lim_{n \to \infty} \mathbb{P}\bigl(|\bar{X}_n - \mu| \ge \varepsilon\bigr) = 0.
\]
\end{theorem}

\begin{proof}
By linearity, $\mathbb{E}[\bar{X}_n] = \mu$. Because the $X_i$ are pairwise uncorrelated, the variance of their sum is the sum of their variances, so
\begin{align*}
\operatorname{Var}(\bar{X}_n) = \frac{1}{n^2} \sum_{i=1}^n \operatorname{Var}(X_i) = \frac{\sigma^2}{n}.
\end{align*}
Theorem~\ref{thm:chebyshev} then gives
\[
  0 \le \mathbb{P}\bigl(|\bar{X}_n - \mu| \ge \varepsilon\bigr) \le \frac{\sigma^2}{n \varepsilon^2},
\]
and the right side tends to $0$ as $n \to \infty$.
\end{proof}

\begin{remark}
Both inequalities are sharp in the sense that equality can occur. For Markov, take $X$ equal to $a$ with probability $p$ and $0$ otherwise; then $\mathbb{P}(X \ge a) = p = \mathbb{E}[X]/a$. For Chebyshev, take $X$ equal to $\mu \pm k$ each with probability $\sigma^2/(2k^2)$ and to $\mu$ otherwise, where $\sigma \le k$.
\end{remark}

